package com.bank.techchoice.model;

// A candidate technology scored on project-relevant factors, plus its genuine strength.
public class TechOption {
    private final String name;
    private final int fit;          // problem fit (ledger needs ACID)
    private final int performance;
    private final int teamSkill;    // team familiarity
    private final int maturity;     // ecosystem, security track record
    private final int opsCost;      // higher = cheaper/easier to operate
    private final String strength;  // honest note of what this option is good at

    public TechOption(String name, int fit, int performance, int teamSkill,
                      int maturity, int opsCost, String strength) {
        this.name = name;
        this.fit = fit;
        this.performance = performance;
        this.teamSkill = teamSkill;
        this.maturity = maturity;
        this.opsCost = opsCost;
        this.strength = strength;
    }

    public String getName() { return name; }
    public int getFit() { return fit; }
    public int getPerformance() { return performance; }
    public int getTeamSkill() { return teamSkill; }
    public int getMaturity() { return maturity; }
    public int getOpsCost() { return opsCost; }
    public String getStrength() { return strength; }
}
